    private static let parsedSides: [String: [UInt32: (Double, Double)]] = {
        var all: [String: [UInt32: (Double, Double)]] = [:]
        for (face, raw) in sides {
            var t: [UInt32: (Double, Double)] = [:]
            for item in raw.split(separator: " ") {
                let a = item.split(separator: ":"), b = a.count == 2 ? a[1].split(separator: ",") : []
                if b.count == 2, let c = UInt32(a[0], radix: 16), let lo = Double(b[0]), let hi = Double(b[1]) { t[c] = (lo / 1000, hi / 1000) }
            }
            all[face] = t
        }
        return all
    }()
    /// The glyph's real ink (left, right) in em from its origin, nil where the face or the character is not in the table.
    static func horizontal(face: String, bold: Bool, _ ch: String) -> (Double, Double)? {
        guard ch.unicodeScalars.count == 1, let u = ch.unicodeScalars.first?.value else { return nil }
        if bold, let t = parsedSides[face + " Bold"] { return t[u] }
        return parsedSides[face]?[u]
    }
}
